import sys
import math


def main():
    tok = sys.stdin.buffer.read().replace(b',', b' ').split()
    cats = tok[4::3]
    vals = tok[5::3]
    groups = {}
    for c, v in zip(cats, map(float, vals)):
        lst = groups.get(c)
        if lst is None:
            groups[c] = [v]
        else:
            lst.append(v)
    out = [c.decode() + ',' + ('%.2f' % math.fsum(groups[c])) for c in sorted(groups)]
    if out:
        sys.stdout.write('\n'.join(out) + '\n')


main()
